$('start').onclick=()=>startGame();$('guide-open').onclick=guide;$('pause').onclick=pauseGame;document.querySelectorAll('.sound-toggle').forEach(b=>b.onclick=toggleSound);$('touch-dash').onclick=doDash;$('touch-ult').onclick=ultimate;$('touch-art').onclick=signature;$('interact-tip').onclick=()=>{if(game?.nearEvent)openEvent(game.nearEvent);};
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&state!=='home')e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(state==='playing'&&!qaRunning)pauseGame();else if(state==='paused'||state==='book')closeModal();else if(state==='guide')$('guide-close').click();return;}if(e.code==='KeyB'&&game){if(state==='book')closeModal();else if(state==='playing'||state==='paused')openBook();return;}if(state==='upgrade'&&['Digit1','Digit2','Digit3'].includes(e.code)){const id=game.choices[+e.code.slice(-1)-1];if(id)selectUpgrade(id);return;}if(state!=='playing')return;keys.add(e.code);if(e.code==='Space')doDash();if(e.code==='KeyQ')ultimate();if(e.code==='KeyE')signature();});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();stick.x=stick.z=0;pointer.held=false;if(state==='playing'&&!qaRunning)pauseGame();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'&&!qaRunning)pauseGame();});
$('world').addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&state==='playing'){pointer.x=e.clientX/innerWidth*2-1;pointer.y=1-e.clientY/innerHeight*2;pointer.active=true;}});$('world').addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){pointer.held=true;pointer.active=true;pointer.x=e.clientX/innerWidth*2-1;pointer.y=1-e.clientY/innerHeight*2;}});addEventListener('pointerup',()=>pointer.held=false);$('world').addEventListener('pointerleave',()=>pointer.active=false);
let stickId=null;const stickEl=$('stick');function moveStick(e){const r=stickEl.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.hypot(dx,dy),scale=Math.min(34,d)/Math.max(d,1);stick.x=dx*scale/34;stick.z=dy*scale/34;stickEl.firstElementChild.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
stickEl.addEventListener('pointerdown',e=>{stickId=e.pointerId;stickEl.setPointerCapture(e.pointerId);moveStick(e);});stickEl.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e);});for(const type of ['pointerup','pointercancel'])stickEl.addEventListener(type,()=>{stickId=null;stick.x=stick.z=0;stickEl.firstElementChild.style.transform='';});

